package com.bocsoft.sqleditor.execution;
import com.bocsoft.sqleditor.execution.api.BinaryValue;import java.math.BigDecimal;import java.sql.*;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class JdbcValueEncoderTest {private final JdbcValueEncoder encoder=new JdbcValueEncoder();@Test void preservesPrecisionNullAndBinarySize()throws Exception{ResultSet rs=mock(ResultSet.class);when(rs.getObject(1)).thenReturn(9007199254740993L);when(rs.getObject(2)).thenReturn(new BigDecimal("123.4500"));when(rs.getObject(3)).thenReturn(null);when(rs.getObject(4)).thenReturn(new byte[]{1,2,3});when(rs.getBytes(4)).thenReturn(new byte[]{1,2,3});assertThat(encoder.encode(rs,1,Types.BIGINT)).isEqualTo("9007199254740993");assertThat(encoder.encode(rs,2,Types.DECIMAL)).isEqualTo("123.4500");assertThat(encoder.encode(rs,3,Types.VARCHAR)).isNull();assertThat(((BinaryValue)encoder.encode(rs,4,Types.BLOB)).getSize()).isEqualTo(3);}}
